-- CP6 AY PO HPP corrections dated from the goods: T1_FAMILY development install (NOT a release package).
-- Generated by scripts/cp6_ay_build.py from the AS definition of erp.sync_po_hpp_to_gl; do not edit by hand.
begin;
set local lock_timeout='10s';set local statement_timeout='240s';set local search_path='';
do $t1_guard$
begin
 if (select count(*) from erp.schema_migrations where version in('v2.6.20av','v2.6.20aw','v2.6.20ax'))<>3 then raise exception 'AY_T1_REQUIRES_AV_AW_AX'; end if;
 if exists(select 1 from erp.schema_migrations where version='v2.6.20ay') or to_regprocedure('erp.po_hpp_gl_leg_add_v1(jsonb,date,numeric,numeric,numeric)') is not null or to_regclass('erp.po_hpp_gl_lot_state_v1') is not null or to_regclass('erp.po_hpp_gl_material_state_v1') is not null then raise exception 'AY_T1_ALREADY_INSTALLED'; end if;
end $t1_guard$;
create table erp.po_hpp_gl_lot_state_v1(
  lot_id uuid primary key,
  po_id uuid not null,
  hpp_per_pcs numeric not null,
  updated_at timestamptz not null default statement_timestamp(),
  pocket_by_pool jsonb);
comment on table erp.po_hpp_gl_lot_state_v1 is 'AY: HPP per piece of each lot as erp.sync_po_hpp_to_gl last posted it (base of the per-lot correction of the next sync).';
alter table erp.po_hpp_gl_lot_state_v1 enable row level security;
revoke all on erp.po_hpp_gl_lot_state_v1 from public,anon,authenticated,service_role;
create table erp.po_hpp_gl_material_state_v1(
  po_id uuid not null,
  source_key text not null,
  material_value numeric not null,
  updated_at timestamptz not null default statement_timestamp(),
  primary key(po_id,source_key));
comment on table erp.po_hpp_gl_material_state_v1 is 'AY rev7: value of each material fact behind a PO HPP (cutting issue/return M:<movement>, also of other POs'' groups in the same cutting batch; contractor issue C:<item>) as that PO''s last erp.sync_po_hpp_to_gl saw it; base of the per-fact correction dated on its own day.';
alter table erp.po_hpp_gl_material_state_v1 enable row level security;
revoke all on erp.po_hpp_gl_material_state_v1 from public,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION erp.po_hpp_gl_leg_add_v1(p_acc jsonb, p_day date, p_fg numeric, p_cogs numeric, p_other numeric)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
-- AY: add one dated leg (FG, COGS, other) to the per-date accumulator of erp.sync_po_hpp_to_gl.
select coalesce(p_acc,'{}'::jsonb)||jsonb_build_object(p_day::text,jsonb_build_object(
  'fg',coalesce((p_acc->(p_day::text)->>'fg')::numeric,0)+coalesce(p_fg,0),
  'cogs',coalesce((p_acc->(p_day::text)->>'cogs')::numeric,0)+coalesce(p_cogs,0),
  'other',coalesce((p_acc->(p_day::text)->>'other')::numeric,0)+coalesce(p_other,0)))
$function$;
revoke all on function erp.po_hpp_gl_leg_add_v1(jsonb,date,numeric,numeric,numeric) from public,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION erp.po_hpp_gl_pocket_by_pool_v1(p_lot_id uuid)
 RETURNS TABLE(pool_id uuid, amount numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with target as(
  select fl.id,fl.po_id,coalesce(fl.cutting_group_id,qi.cutting_group_id) group_id,
    fl.initial_qty_pcs::numeric lot_qty,fl.produced_at
  from erp.fg_lots fl
  left join erp.qc_inspection_items qi on qi.id=fl.qc_item_id
  where fl.id=p_lot_id and fl.lot_origin='PRODUCTION'
), position as(
  select t.*,
    coalesce((select sum(x.initial_qty_pcs)::numeric from erp.fg_lots x
      left join erp.qc_inspection_items xqi on xqi.id=x.qc_item_id
      where x.po_id=t.po_id and x.lot_origin='PRODUCTION'
        and coalesce(x.cutting_group_id,xqi.cutting_group_id)=t.group_id
        and (x.produced_at,x.id)<(t.produced_at,t.id)),0) group_start,
    coalesce((select sum(x.initial_qty_pcs)::numeric from erp.fg_lots x
      where x.po_id=t.po_id and x.lot_origin='PRODUCTION'
        and (x.produced_at,x.id)<(t.produced_at,t.id)),0) po_start
  from target t
), terminal as(
  select e.id,e.po_id,e.cutting_group_id,e.qty_signed::numeric event_qty,
    coalesce(sum(e.qty_signed) over(
      partition by e.po_id,e.cutting_group_id
      order by e.physical_at,e.id rows between unbounded preceding and 1 preceding
    ),0)::numeric group_start,
    coalesce(sum(e.qty_signed) over(
      partition by e.po_id
      order by e.physical_at,e.id rows between unbounded preceding and 1 preceding
    ),0)::numeric po_start
  from erp.sewing_terminal_events e join position p on p.po_id=e.po_id
  where e.event_kind='SELESAI_DIJAHIT' and e.qty_signed>0
    and not exists(select 1 from erp.sewing_terminal_events rv where rv.reversal_of_id=e.id)
), alloc as(
  select a.pool_id,a.cutting_group_id,a.sewing_qty::numeric source_qty,erp.pocket_period_amount_v1(a.pool_id,a.preceding_qty,a.sewing_qty)::numeric source_cost,
    case when a.cutting_group_id is null then t.po_start else t.group_start end source_start
  from position p
  join erp.pocket_period_destinations a on a.po_id=p.po_id
    and (a.cutting_group_id=p.group_id or a.cutting_group_id is null)
  join erp.pocket_periods hp on hp.id=a.pool_id and erp.pocket_period_active_v1(hp.id)
  join terminal t on t.id=a.event_id
)
select a.pool_id,coalesce(sum(
  greatest(least(
    case when a.cutting_group_id is null then p.po_start+p.lot_qty else p.group_start+p.lot_qty end,
    a.source_start+a.source_qty
  )-greatest(
    case when a.cutting_group_id is null then p.po_start else p.group_start end,
    a.source_start
  ),0)*a.source_cost/nullif(a.source_qty,0)
),0)::numeric
from position p join alloc a on true group by a.pool_id
$function$;
revoke all on function erp.po_hpp_gl_pocket_by_pool_v1(uuid) from public,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION erp.rebuild_po_hpp(p_po_id uuid, p_reason text DEFAULT 'Recalculate HPP'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_material numeric(24,6):=0;v_opening_cost numeric(24,6):=0;
  v_material_allocated numeric(24,6):=0;
  v_contractor_material numeric(24,6):=0;
  v_accessory numeric(24,6):=0;
  v_labor numeric(24,6):=0;
  v_commission numeric(24,6):=0;
  v_laundry numeric(24,6):=0;
  v_rework numeric(24,6):=0;
  v_other numeric(24,6):=0;
  v_pocket numeric(24,6):=0;v_pocket_allocated numeric(24,6):=0;v_lot_pocket numeric(24,6):=0;
  v_attendance_hpp numeric(24,6):=0;
  v_shared_attendance_hpp numeric(24,6):=0;
  v_shared_labor numeric(24,6):=0;
  v_shared_commission numeric(24,6):=0;
  v_shared_rework numeric(24,6):=0;
  v_shared_other numeric(24,6):=0;
  v_total_current numeric(24,6):=0;
  v_total_qty integer:=0;
  v_pending boolean:=false;
  r record;
  c record;
  v_old_id uuid;
  v_new_id uuid;
  v_version integer;
  v_lot_accessory numeric(24,6);
  v_lot_cost numeric(24,6);
  v_lot_material numeric(24,6);
  v_pool_material numeric(24,6);
  v_pool_qty numeric(24,6);
  v_batch_id uuid;
  v_state varchar(20);
  v_group_fg_qty numeric(24,6);
  v_group_labor numeric(24,6);
  v_group_commission numeric(24,6);
  v_group_laundry numeric(24,6);
  v_group_rework numeric(24,6);
  v_group_attendance_hpp numeric(24,6);
  v_lot_attendance_hpp numeric(24,6);
  v_lot_labor numeric(24,6);
  v_lot_commission numeric(24,6);
  v_lot_laundry numeric(24,6);
  v_lot_rework numeric(24,6);
  v_lot_other numeric(24,6);
  v_cp6_lineage boolean:=false;
  v_lot_cp6_receipt_laundry numeric(24,6):=0;
  v_lot_cp6_attempt_laundry numeric(24,6):=0;
  v_laundry_allocated numeric(24,6):=0;
  v_labor_allocated numeric(24,6):=0;
  v_commission_allocated numeric(24,6):=0;
  v_rework_allocated numeric(24,6):=0;
  v_attendance_allocated numeric(24,6):=0;
  v_po_source_qty numeric(24,6):=0;
begin
  perform erp.require_internal();
  perform erp.pocket_period_lock_v1();
  select coalesce(sum(erp.pocket_period_amount_v1(d.pool_id,d.preceding_qty,d.sewing_qty)),0) into v_pocket from erp.pocket_period_destinations d where d.po_id=p_po_id;
  -- One lock order covers Draft reservation, post/reversal, late recost, and GL sync.
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  perform pg_advisory_xact_lock(hashtextextended('PO_HPP:'||p_po_id::text,0));

  select coalesce(sum(-msm.qty_signed*msm.unit_cost_snapshot),0) into v_material
  from erp.material_stock_movements msm
  where ((msm.source_type='CUTTING_GROUP' and msm.source_id in (select id from erp.cutting_groups where po_id=p_po_id))
     or (msm.source_type='CUTTING_GROUP_RETURN' and msm.source_id in (select id from erp.cutting_groups where po_id=p_po_id)))
    and not exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id);

  select coalesce(sum(cmii.qty*cmii.unit_cost_snapshot),0) into v_contractor_material
  from erp.contractor_material_issue_items cmii
  join erp.contractor_material_issues cmi on cmi.id=cmii.issue_id
  join erp.materials m on m.id=cmii.material_id
  where cmi.po_id=p_po_id and cmi.status='POSTED' and m.material_type<>'ACCESSORY';

  select
    coalesce(sum(case when wc.component_category='COMMISSION' then wcl.amount_payable else 0 end),0),
    coalesce(sum(case when wc.component_category<>'COMMISSION' then wcl.amount_payable else 0 end),0),
    coalesce(sum(case when wce.cutting_group_id is null and wc.component_category='COMMISSION' then wcl.amount_payable else 0 end),0),
    coalesce(sum(case when wce.cutting_group_id is null and wc.component_category<>'COMMISSION' then wcl.amount_payable else 0 end),0)
  into v_commission,v_labor,v_shared_commission,v_shared_labor
  from erp.work_completion_lines wcl
  join erp.work_completion_events wce on wce.id=wcl.completion_id
  join erp.work_components wc on wc.id=wcl.work_component_id
  where wce.po_id=p_po_id and wce.status='POSTED';

  with dl as (
    select ldl.id,ldl.cutting_group_id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot,
           coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then lrl.qty_good_received+lrl.qty_bs_laundry else 0 end),0) as qty_costed_actual,
           coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then coalesce(lrl.actual_cost,0) else 0 end),0) as actual_cost,
           bool_or(lr.status='POSTED' and lrl.actual_cost_status in('PENDING','ESTIMATED')) as has_pending_receipt
    from erp.laundry_delivery_lines ldl
    join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
    left join erp.laundry_receipt_lines lrl on lrl.delivery_line_id=ldl.id
    left join erp.laundry_receipts lr on lr.id=lrl.receipt_id
    where ld.po_id=p_po_id and ld.status<>'REVERSED'
    group by ldl.id,ldl.cutting_group_id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot
  )
  select coalesce(sum(actual_cost+greatest(qty_sent_pcs-qty_costed_actual,0)*coalesce(estimated_rate_snapshot,0)),0),
         coalesce(bool_or(has_pending_receipt or qty_sent_pcs>qty_costed_actual),false)
  into v_laundry,v_pending from dl;

  select v_laundry+coalesce(sum(rl.actual_cost),0)
    into v_laundry
  from erp.laundry_failed_wash_attempts a
  join erp.laundry_receipt_lines rl on rl.id=a.receipt_line_id
  join erp.laundry_receipts rh on rh.id=a.receipt_id and rh.status='POSTED'
  join erp.laundry_deliveries ld on ld.id=a.delivery_id and ld.status='REVERSED'
  where ld.po_id=p_po_id and rl.actual_cost_status in('ESTIMATED','FINAL');

  v_pending:=v_pending or exists(
    select 1
    from erp.laundry_failed_wash_attempts a
    join erp.laundry_receipts rh on rh.id=a.receipt_id and rh.status='POSTED'
    join erp.laundry_receipt_lines rl on rl.id=a.receipt_line_id
    join erp.laundry_deliveries ld on ld.id=a.delivery_id
    where ld.po_id=p_po_id and rl.actual_cost_status='ESTIMATED'
  );


  select coalesce(sum(rcl.amount_payable),0),
         coalesce(sum(case when bc.cutting_group_id is null then rcl.amount_payable else 0 end),0)
  into v_rework,v_shared_rework
  from erp.rework_component_lines rcl
  join erp.rework_orders ro on ro.id=rcl.rework_order_id
  join erp.bs_cases bc on bc.id=ro.bs_case_id
  where bc.po_id=p_po_id and ro.status<>'CANCELLED' and coalesce(ro.cost_posted,false)=true;

  select coalesce(sum(adjustment_amount),0),coalesce(sum(case when lot_id is null then adjustment_amount else 0 end),0)
  into v_other,v_shared_other
  from erp.cost_adjustments
  where po_id=p_po_id and component_type='OTHER';

  select
    coalesce(sum(a.allocated_amount),0),
    coalesce(sum(case when a.cutting_group_id is null then a.allocated_amount else 0 end),0)
  into v_attendance_hpp,v_shared_attendance_hpp
  from erp.attendance_hpp_pool_allocations a
  join erp.attendance_hpp_pools hp on hp.id=a.pool_id and hp.status='ACTIVE'
  where a.po_id=p_po_id;

  select coalesce(sum(initial_qty_pcs),0) into v_total_qty
  from erp.fg_lots where po_id=p_po_id and lot_origin='PRODUCTION';
  if v_total_qty<=0 then return; end if;
  v_po_source_qty:=erp.cp6_po_source_qty_v2620c(p_po_id);
  if coalesce(v_po_source_qty,0)<=0 then
    raise exception 'PO source quantity is required before HPP can be allocated';
  end if;

  for r in select id from erp.fg_lots where po_id=p_po_id and lot_origin='PRODUCTION' order by produced_at,id
  loop perform erp.ensure_fg_accessory_cost_snapshot(r.id); end loop;

  select coalesce(sum(facs.total_hpp_cost),0) into v_accessory
  from erp.fg_accessory_cost_snapshots facs join erp.fg_lots fl on fl.id=facs.lot_id
  where fl.po_id=p_po_id and fl.lot_origin='PRODUCTION';

  v_pending:=v_pending or exists(select 1 from erp.initial_import_production_sources s
    join erp.initial_import_cost_origins o on o.opening_item_id=s.opening_item_id where s.po_id=p_po_id
    and erp.material_purchase_invoice_capacity(o.purchase_item_id)>erp.material_purchase_posted_invoice_qty(o.purchase_item_id));
  v_state:=case when v_pending then 'ESTIMATED' when exists (select 1 from erp.cost_adjustments where po_id=p_po_id) then 'ADJUSTED' else 'ACTUAL' end;

  for r in
    select fl.*,coalesce(fl.qc_item_id,(
      select bc.qc_item_id from erp.rework_orders ro
      join erp.bs_cases bc on bc.id=ro.bs_case_id
      where ro.good_fg_lot_id=fl.id
    )) as source_qc_item_id,
      coalesce(fl.cutting_group_id,qi.cutting_group_id) as lineage_group_id
    from erp.fg_lots fl left join erp.qc_inspection_items qi on qi.id=fl.qc_item_id
    where fl.po_id=p_po_id and fl.lot_origin='PRODUCTION'
    order by fl.produced_at,fl.id
  loop
    v_lot_material:=0;v_pool_material:=0;v_pool_qty:=0;v_batch_id:=null;
    v_group_fg_qty:=0;v_group_labor:=0;v_group_commission:=0;v_group_laundry:=0;v_group_rework:=0;v_group_attendance_hpp:=0;
    v_cp6_lineage:=false;v_lot_cp6_receipt_laundry:=0;v_lot_cp6_attempt_laundry:=0;

    if r.lineage_group_id is not null then
      select cutting_batch_id into v_batch_id from erp.cutting_groups where id=r.lineage_group_id;
      if v_batch_id is not null then
        select coalesce(sum(-msm.qty_signed*msm.unit_cost_snapshot),0) into v_pool_material
        from erp.material_stock_movements msm
        where ((msm.source_type='CUTTING_GROUP' and msm.source_id in (select id from erp.cutting_groups where cutting_batch_id=v_batch_id))
           or (msm.source_type='CUTTING_GROUP_RETURN' and msm.source_id in (select id from erp.cutting_groups where cutting_batch_id=v_batch_id)))
          and not exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id);
        select effective_pcs::numeric into v_pool_qty from erp.v_cutting_batch_totals where cutting_batch_id=v_batch_id;
      else
        select coalesce(sum(-msm.qty_signed*msm.unit_cost_snapshot),0) into v_pool_material
        from erp.material_stock_movements msm
        where msm.source_id=r.lineage_group_id and msm.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN')
          and not exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id);
        select total_pcs::numeric into v_pool_qty from erp.v_cutting_group_totals where cutting_group_id=r.lineage_group_id;
      end if;

      select coalesce(sum(fl2.initial_qty_pcs),0)::numeric into v_group_fg_qty
      from erp.fg_lots fl2 where fl2.po_id=p_po_id and fl2.lot_origin='PRODUCTION' and fl2.cutting_group_id=r.lineage_group_id;

      select
        coalesce(sum(case when wc.component_category<>'COMMISSION' then wcl.amount_payable else 0 end),0),
        coalesce(sum(case when wc.component_category='COMMISSION' then wcl.amount_payable else 0 end),0)
      into v_group_labor,v_group_commission
      from erp.work_completion_lines wcl
      join erp.work_completion_events wce on wce.id=wcl.completion_id
      join erp.work_components wc on wc.id=wcl.work_component_id
      where wce.po_id=p_po_id and wce.status='POSTED' and wce.cutting_group_id=r.lineage_group_id;

      with dl as (
        select ldl.id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot,
               coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then lrl.qty_good_received+lrl.qty_bs_laundry else 0 end),0) as qty_costed_actual,
               coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then coalesce(lrl.actual_cost,0) else 0 end),0) as actual_cost
        from erp.laundry_delivery_lines ldl
        join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
        left join erp.laundry_receipt_lines lrl on lrl.delivery_line_id=ldl.id
        left join erp.laundry_receipts lr on lr.id=lrl.receipt_id
        where ld.po_id=p_po_id and ld.status<>'REVERSED' and ldl.cutting_group_id=r.lineage_group_id
        group by ldl.id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot
      )
      select coalesce(sum(actual_cost+greatest(qty_sent_pcs-qty_costed_actual,0)*coalesce(estimated_rate_snapshot,0)),0)
      into v_group_laundry from dl;

      select v_group_laundry+coalesce(sum(rl.actual_cost),0)
        into v_group_laundry
      from erp.laundry_failed_wash_attempts a
      join erp.laundry_receipt_lines rl on rl.id=a.receipt_line_id
      join erp.laundry_receipts rh on rh.id=a.receipt_id and rh.status='POSTED'
      join erp.laundry_deliveries ld on ld.id=a.delivery_id and ld.status='REVERSED'
      join erp.laundry_delivery_lines ldl on ldl.delivery_id=ld.id
      where ld.po_id=p_po_id and ldl.cutting_group_id=r.lineage_group_id
        and rl.actual_cost_status in('ESTIMATED','FINAL');


      select coalesce(sum(rcl.amount_payable),0) into v_group_rework
      from erp.rework_component_lines rcl
      join erp.rework_orders ro on ro.id=rcl.rework_order_id
      join erp.bs_cases bc on bc.id=ro.bs_case_id
      where bc.po_id=p_po_id and bc.cutting_group_id=r.lineage_group_id and ro.status<>'CANCELLED' and coalesce(ro.cost_posted,false)=true;

      select coalesce(sum(a.allocated_amount),0) into v_group_attendance_hpp
      from erp.attendance_hpp_pool_allocations a
      join erp.attendance_hpp_pools hp on hp.id=a.pool_id and hp.status='ACTIVE'
      where a.po_id=p_po_id and a.cutting_group_id=r.lineage_group_id;
    end if;

    select exists(
      select 1
      from erp.qc_inspection_items qi
      join erp.laundry_receipt_batch_size_lines rx
        on rx.id=qi.source_laundry_receipt_batch_size_line_id
      where qi.id=r.source_qc_item_id
    ) into v_cp6_lineage;

    if v_cp6_lineage then
      select coalesce((case
          when rl.actual_cost_status in('ESTIMATED','FINAL') and rl.actual_cost is not null
            then rl.actual_cost/nullif(rl.qty_good_received+rl.qty_bs_laundry,0)
          else coalesce(rl.actual_rate_snapshot,dl.estimated_rate_snapshot,0)
        end)*r.initial_qty_pcs,0)
      into v_lot_cp6_receipt_laundry
      from erp.qc_inspection_items qi
      join erp.laundry_receipt_batch_size_lines rx
        on rx.id=qi.source_laundry_receipt_batch_size_line_id
      join erp.laundry_receipt_lines rl on rl.id=rx.receipt_line_id
        and rl.id=qi.source_laundry_receipt_line_id
      join erp.laundry_receipts rh on rh.id=rl.receipt_id and rh.status='POSTED'
      join erp.laundry_delivery_lines dl on dl.id=rl.delivery_line_id
      join erp.laundry_deliveries d on d.id=dl.delivery_id and d.status<>'REVERSED'
      left join erp.laundry_failed_wash_attempts fa on fa.receipt_line_id=rl.id
      where qi.id=r.source_qc_item_id and fa.id is null;
      v_lot_cp6_receipt_laundry:=coalesce(v_lot_cp6_receipt_laundry,0);

      select erp.cp6_lot_failed_wash_cost_v2620e(r.id)
      into v_lot_cp6_attempt_laundry;
    end if;

    if coalesce(v_pool_qty,0)>0 then v_lot_material:=v_pool_material*(r.initial_qty_pcs::numeric/v_pool_qty);
    else v_lot_material:=v_material*(r.initial_qty_pcs::numeric/v_total_qty::numeric); end if;
    v_lot_material:=v_lot_material+v_contractor_material*(r.initial_qty_pcs::numeric/v_po_source_qty);
    v_material_allocated:=v_material_allocated+v_lot_material;

    v_lot_labor:=erp.cp6_lot_work_cost_v2620c(r.id,'LABOR');
    v_lot_commission:=erp.cp6_lot_work_cost_v2620c(r.id,'COMMISSION');
    v_lot_laundry:=case when v_cp6_lineage
      then v_lot_cp6_receipt_laundry+v_lot_cp6_attempt_laundry
      when r.lineage_group_id is not null then v_group_laundry*(r.initial_qty_pcs::numeric/nullif(
        coalesce(nullif((select total_pcs::numeric from erp.v_cutting_group_totals
          where cutting_group_id=r.lineage_group_id),0),v_po_source_qty),0))
      else v_laundry*(r.initial_qty_pcs::numeric/v_po_source_qty) end;
    v_lot_rework:=erp.cp6_lot_rework_cost_v2620c(r.id);
    v_lot_attendance_hpp:=erp.cp6_lot_attendance_cost_v2620c(r.id);
    v_lot_pocket:=erp.pocket_lot_cost_v1(r.id);v_pocket_allocated:=v_pocket_allocated+v_lot_pocket;

    select coalesce(sum(total_hpp_cost),0) into v_lot_accessory from erp.fg_accessory_cost_snapshots where lot_id=r.id;
    select coalesce(sum(adjustment_amount),0) into v_lot_other from erp.cost_adjustments where lot_id=r.id and component_type='OTHER';
    v_lot_other:=v_lot_other+v_shared_other*(r.initial_qty_pcs::numeric/v_po_source_qty);
    v_laundry_allocated:=v_laundry_allocated+v_lot_laundry;
    v_labor_allocated:=v_labor_allocated+v_lot_labor;
    v_commission_allocated:=v_commission_allocated+v_lot_commission;
    v_rework_allocated:=v_rework_allocated+v_lot_rework;
    v_attendance_allocated:=v_attendance_allocated+v_lot_attendance_hpp;
    v_opening_cost:=erp.initial_import_lot_cost_v1(r.id);
    v_lot_cost:=v_opening_cost+v_lot_material+v_lot_labor+v_lot_commission+v_lot_laundry+v_lot_rework+v_lot_attendance_hpp+v_lot_other+v_lot_accessory+v_lot_pocket;
    v_total_current:=v_total_current+v_lot_cost;

    select id into v_old_id from erp.hpp_versions where lot_id=r.id and is_current=true order by version_no desc limit 1;
    select coalesce(max(version_no),0)+1 into v_version from erp.hpp_versions where lot_id=r.id;
    if v_old_id is not null then update erp.hpp_versions set is_current=false where id=v_old_id; end if;

    insert into erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,supersedes_id,calculation_reason,created_by)
    values (r.id,v_version,v_state,r.initial_qty_pcs,v_lot_cost,true,v_old_id,p_reason,erp.current_app_user_id()) returning id into v_new_id;

    insert into erp.hpp_version_components(hpp_version_id,component_type,description,total_cost,source_type,source_id)
    values
      (v_new_id,'MATERIAL',case when v_batch_id is not null then 'Cutting material by effective batch yield + PO-shared non-accessory contractor material' else 'Cutting/legacy material pool + PO-shared non-accessory contractor material' end,v_lot_material,case when v_batch_id is not null then 'CUTTING_BATCH' else 'PO' end,coalesce(v_batch_id,p_po_id)),
      (v_new_id,'LABOR','Labor allocation: immutable component completion intervals; unfinished remains WIP',v_lot_labor,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),
      (v_new_id,'COMMISSION','Commission allocation: immutable component completion intervals; unfinished remains WIP',v_lot_commission,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),
      (v_new_id,'LAUNDRY',case when v_cp6_lineage
        then 'CP6 exact receipt/batch-size service lineage; unfinished cost remains WIP'
        else 'Legacy Laundry allocation from same cutting group; PENDING uses estimate' end,
        v_lot_laundry,case when v_cp6_lineage then 'QC_ITEM'
          when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,
        case when v_cp6_lineage then r.source_qc_item_id else coalesce(r.lineage_group_id,p_po_id) end),
      (v_new_id,'REWORK','Rework allocation: exact good rework lot and qty-sent source',v_lot_rework,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),
      (v_new_id,'LABOR','Attendance HPP: ACTIVE source sewing intervals; unfinished remains WIP',v_lot_attendance_hpp,'ATTENDANCE_HPP_ACTIVE_ALLOCATION',coalesce(r.lineage_group_id,p_po_id)),
      (v_new_id,'OTHER','Kain kantong: pembagian periode selesai dijahit',v_lot_pocket,'POCKET_PERIOD_ALLOCATION',p_po_id),
      (v_new_id,'OTHER','Other/adjustment allocation',v_lot_other,'PO',p_po_id),
      (v_new_id,'OTHER','Saldo fisik sebelum cutover',v_opening_cost,'INITIAL_IMPORT_PRODUCTION',r.id);

    for c in
      select facs.id,facs.total_hpp_cost,ac.category_name,facs.hpp_method
      from erp.fg_accessory_cost_snapshots facs join erp.accessory_categories ac on ac.id=facs.category_id
      where facs.lot_id=r.id order by ac.category_code
    loop
      insert into erp.hpp_version_components(hpp_version_id,component_type,description,total_cost,source_type,source_id)
      values (v_new_id,'ACCESSORY','Accessory category: '||c.category_name||' ['||c.hpp_method||']',c.total_hpp_cost,'FG_ACCESSORY_SNAPSHOT',c.id);
    end loop;

    update erp.fg_stock_movements set unit_hpp_snapshot=(select hpp_per_pcs from erp.hpp_versions where id=v_new_id)
    where lot_id=r.id and movement_type in ('QC_GOOD','REWORK_IN');
  end loop;

  if v_pocket_allocated < -0.005 or v_pocket_allocated>v_pocket+0.005 then raise exception 'Pocket HPP cost conservation failed';end if;
  if v_labor_allocated < -0.005 or v_labor_allocated > v_labor+0.005
     or v_commission_allocated < -0.005 or v_commission_allocated > v_commission+0.005
     or v_rework_allocated < -0.005 or v_rework_allocated > v_rework+0.005
     or v_attendance_allocated < -0.005 or v_attendance_allocated > v_attendance_hpp+0.005 then
    raise exception 'CP6 source-owned HPP allocation violates cost conservation: labor %/%, commission %/%, rework %/%, attendance %/%',
      v_labor_allocated,v_labor,v_commission_allocated,v_commission,
      v_rework_allocated,v_rework,v_attendance_allocated,v_attendance_hpp;
  end if;

  if v_laundry_allocated < -0.005 or v_laundry_allocated > v_laundry+0.005 then
    raise exception 'CP6 Laundry HPP allocation violates cost conservation: accrued %, FG allocated %',
      v_laundry,v_laundry_allocated;
  end if;

  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values ('production_orders',p_po_id,'RECALCULATE',jsonb_build_object(
    'material_total_issued',v_material+v_contractor_material,'cutting_material_total',v_material,'contractor_nonaccessory_material_total',v_contractor_material,'material_allocated_to_current_fg',v_material_allocated,'material_basis','CUTTING_BATCH_EFFECTIVE_YIELD_PLUS_PO_SHARED_CONTRACTOR_MATERIAL',
    'pocket_fabric',v_pocket,'pocket_allocated_to_fg',v_pocket_allocated,'pocket_remaining_in_wip',v_pocket-v_pocket_allocated,
    'accessory',v_accessory,'labor',v_labor,'attendance_hpp',v_attendance_hpp,'commission',v_commission,'laundry',v_laundry,'rework',v_rework,'other',v_other,
    'laundry_allocated_to_current_fg',v_laundry_allocated,
    'laundry_remaining_in_wip',v_laundry-v_laundry_allocated,
    'labor_allocated_to_fg',v_labor_allocated,'labor_remaining_in_wip',v_labor-v_labor_allocated,
    'commission_allocated_to_fg',v_commission_allocated,'commission_remaining_in_wip',v_commission-v_commission_allocated,
    'rework_allocated_to_fg',v_rework_allocated,'rework_remaining_in_wip',v_rework-v_rework_allocated,
    'attendance_allocated_to_fg',v_attendance_allocated,'attendance_remaining_in_wip',v_attendance_hpp-v_attendance_allocated,
    'po_physical_source_qty',v_po_source_qty,
    'laundry_basis','CP6_EXACT_DELIVERY_SIZE_CUSTODY_INTERVAL_V2620C',
    'total_current_fg_cost',v_total_current,'cost_state',v_state,'nonmaterial_basis','CUTTING_GROUP_LINEAGE_WITH_PO_SHARED_FALLBACK','accessory_basis','GOOD_FG_X_CATEGORY_BOM'),
    erp.current_app_user_id(),p_reason);
end;
$function$;
CREATE OR REPLACE FUNCTION erp.sync_po_hpp_to_gl(p_po_id uuid, p_effective_date date DEFAULT ((statement_timestamp() AT TIME ZONE 'Asia/Jakarta'::text))::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
 SET jit TO 'off'
AS $function$
declare
  t record;
  s erp.po_hpp_gl_state%rowtype;
  v_target_qty integer:=0;
  v_target_hpp numeric(24,6):=0;
  v_target_fg numeric(24,6):=0;
  v_target_cogs numeric(24,6):=0;
  v_target_other numeric(24,6):=0;
  v_df numeric(24,6);v_dc numeric(24,6);v_do numeric(24,6);v_sum numeric(24,6);
  v_lines jsonb:='[]'::jsonb;v_event uuid;v_journal uuid;v_documented_gain numeric(24,6):=0;
  v_acc jsonb:='{}'::jsonb;v_f numeric(24,6);v_c numeric(24,6);v_o numeric(24,6);v_wip numeric(24,6);r record;
  v_cap date;v_end date;v_sf numeric(24,6):=0;v_sc numeric(24,6):=0;v_so numeric(24,6):=0;v_caller date:=p_effective_date;
begin
  perform erp.require_internal();
  p_effective_date:=coalesce(erp.invoice_recost_economic_date_v1(),p_effective_date);
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  select * into t from erp.compute_po_hpp_gl_targets_v2620d(p_po_id);
  select * into s from erp.po_hpp_gl_state where po_id=p_po_id for update;

  if coalesce(t.base_output_qty,0)>0 then
    v_target_qty:=t.base_output_qty;
    -- Cumulative targets, deltas, journal lines, and saved state all use the
    -- same minor-unit values. The balancing bucket receives the deterministic remainder.
    v_target_hpp:=round(coalesce(t.hpp_total_cost,0),2);
    v_target_fg:=round(coalesce(t.fg_value,0),2);
    v_target_cogs:=round(coalesce(t.cogs_value,0),2);
    v_target_other:=v_target_hpp-v_target_fg-v_target_cogs;

    with lot_hpp as(
      select fl.id lot_id,case when coalesce(hv.qty_basis_pcs,0)>0
        then hv.total_cost/hv.qty_basis_pcs else 0 end::numeric hpp_per_pcs
      from erp.fg_lots fl left join erp.hpp_versions hv on hv.lot_id=fl.id and hv.is_current=true
      where fl.po_id=p_po_id and fl.lot_origin<>'VOIDED_PRODUCTION'
    ), adj_net as(
      select fm.lot_id,sum(fm.qty_signed)::numeric qty
      from erp.fg_stock_movements fm join erp.fg_lots fl on fl.id=fm.lot_id
      where fl.po_id=p_po_id and fl.lot_origin<>'VOIDED_PRODUCTION'
        and((fm.movement_type='ADJUSTMENT' and fm.source_type='FG_ADJUSTMENT_ITEM')
          or(fm.movement_type='REVERSAL' and exists(
            select 1 from erp.fg_stock_movements orig where orig.id=fm.reversal_of_id
              and orig.movement_type='ADJUSTMENT' and orig.source_type='FG_ADJUSTMENT_ITEM')))
      group by fm.lot_id
    )
    select coalesce(sum(greatest(a.qty,0)*lh.hpp_per_pcs),0) into v_documented_gain
    from adj_net a join lot_hpp lh on lh.lot_id=a.lot_id;
    if v_target_other < -v_documented_gain-0.01 then
      raise exception 'PO HPP allocation inconsistent: financial FG + net sold exceeds production output without a matching documented positive FG adjustment';
    end if;
  else
    v_target_qty:=0;v_target_hpp:=0;v_target_fg:=0;v_target_cogs:=0;v_target_other:=0;
    if s.po_id is null then return; end if;
  end if;

  v_df:=v_target_fg-round(coalesce(s.fg_value,0),2);
  v_dc:=v_target_cogs-round(coalesce(s.cogs_value,0),2);
  v_do:=v_target_other-round(coalesce(s.other_out_value,0),2);
  v_sum:=v_df+v_dc+v_do;

  -- AY (owner, 24 Sep 2026): on the late supplier invoice path the correction of each piece is dated from the physical
  -- facts of that piece: WIP -> FG when it enters FG, FG -> COGS when it is sold (back when returned or when the sale is
  -- reversed), FG -> other when it is written off, BS'd or relabelled; never before the piece was there. Per-account
  -- totals equal the previous single journal (the last date takes the exact remainder).
  -- The period rule is applied as before AY when the effective date E is already closed: every date is capped at E,
  -- so the correction is one journal with economic date E that post_journal (erp.resolve_accounting_transaction_date)
  -- posts on the recognition day; no report before that day changes and the economic date is kept. Only an open E
  -- moves forward to the goods (an open E caps the physical dates at today: the product allows a physical time a few
  -- minutes ahead of the clock).
  v_cap:=erp._cp3_business_date(statement_timestamp());
  if exists(select 1 from erp.accounting_period_control c
            where c.singleton_id=1 and c.closed_through is not null and p_effective_date<=c.closed_through) then
    v_cap:=p_effective_date;
  end if;
  if erp.invoice_recost_economic_date_v1() is null then
  -- Independent review 24 Sep (M1): outside a late supplier invoice the posting is exactly the AS posting (one journal on
  -- the caller's date); several callers pass a physical date (FG adjustment, QC, laundry receipt, ...), whose write-off
  -- must stay on that date.
  if abs(v_df)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_df>0
    then jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_df,'credit',0,'po_id',p_po_id)
    else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(v_df),'po_id',p_po_id) end); end if;
  if abs(v_dc)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_dc>0
    then jsonb_build_object('mapping_key','COGS','debit',v_dc,'credit',0,'po_id',p_po_id)
    else jsonb_build_object('mapping_key','COGS','debit',0,'credit',abs(v_dc),'po_id',p_po_id) end); end if;
  if abs(v_do)>0.005 then
    if v_do>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','OTHER_EXPENSE','debit',v_do,'credit',0,'po_id',p_po_id));
    else v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','OTHER_INCOME','debit',0,'credit',abs(v_do),'po_id',p_po_id)); end if;
  end if;
  if abs(v_sum)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_sum>0
    then jsonb_build_object('mapping_key','WIP','debit',0,'credit',v_sum,'po_id',p_po_id)
    else jsonb_build_object('mapping_key','WIP','debit',abs(v_sum),'credit',0,'po_id',p_po_id) end); end if;

  if jsonb_array_length(v_lines)>=2 then
    insert into erp.po_hpp_gl_events(po_id,effective_date,old_hpp_total,new_hpp_total,fg_delta,cogs_delta,other_delta)
    values(p_po_id,p_effective_date,round(coalesce(s.hpp_total_cost,0),2),v_target_hpp,v_df,v_dc,v_do)
    returning id into v_event;
    v_journal:=erp.post_journal('PO_HPP_GL_SYNC',v_event,p_effective_date,
      'Latest corrected HPP allocation · exact minor-unit targets',v_lines);
    update erp.po_hpp_gl_events set journal_entry_id=v_journal,
      effective_date=(select transaction_date from erp.journal_entries where id=v_journal) where id=v_event;
  end if;

  else
  -- rev6/rev7 (independent reviews 24 Sep of rev4, rev5 and rev6): daily balances. For every date D of a physical fact
  -- (an FG movement of the PO's lots, including reversals and voided lots; a material fact behind the PO's HPP; the
  -- cutting day of a group in a cutting batch) the correction held in FG, COGS and other is each lot's per-piece
  -- correction as of D times its pieces in FG, sold (sales and returns and their reversals) and out otherwise
  -- (adjustment, BS, relabel, and their reversals) as of D; each date posts the change of those balances (cents), WIP
  -- balancing, and the last date the exact remainder to the targets. Per-piece correction of a lot: its HPP now minus
  -- the HPP last posted (erp.po_hpp_gl_lot_state_v1 when written with or after the PO state; else the version current
  -- at the last sync; else the lot's first version, for a lot made by a flow that does not sync, e.g. a relabel; else
  -- zero), less the part of its material correction whose fact (erp.po_hpp_gl_material_state_v1) is dated after D.
  v_end:=p_effective_date;
  for r in
    with recursive lot0 as(
      select fl.id,fl.lot_origin,coalesce(fl.cutting_group_id,qi.cutting_group_id) grp,
        coalesce((select max(case when coalesce(hv.qty_basis_pcs,0)>0 then hv.total_cost/hv.qty_basis_pcs else 0 end)
                  from erp.hpp_versions hv where hv.lot_id=fl.id and hv.is_current),0)::numeric h,
        coalesce((select ls.hpp_per_pcs from erp.po_hpp_gl_lot_state_v1 ls where ls.lot_id=fl.id),
                 (select case when coalesce(ov.qty_basis_pcs,0)>0 then ov.total_cost/ov.qty_basis_pcs else 0 end
                  from erp.hpp_versions ov where ov.lot_id=fl.id and ov.calculated_at<=s.updated_at
                  order by ov.calculated_at desc,ov.version_no desc limit 1),
                 (select case when coalesce(fv.qty_basis_pcs,0)>0 then fv.total_cost/fv.qty_basis_pcs else 0 end
                  from erp.hpp_versions fv where fv.lot_id=fl.id order by fv.version_no,fv.calculated_at limit 1),0)::numeric o,
        (select pa.source_lot_id from erp.product_conversion_allocations pa where pa.destination_lot_id=fl.id order by pa.id limit 1) src,
        (select pc.status from erp.product_conversion_allocations pa join erp.product_conversions pc on pc.id=pa.conversion_id
          where pa.destination_lot_id=fl.id order by pa.id limit 1) cst,
        -- Fallback for a lot without per-pool pocket state (synced before AY rev7.3): the pocket-fabric part of the lot HPP
        -- (component POCKET_PERIOD_ALLOCATION) per piece now less the version before this statement.
        coalesce((select coalesce((select sum(c.total_cost) from erp.hpp_version_components c
                    where c.hpp_version_id=hv.id and c.source_type='POCKET_PERIOD_ALLOCATION'),0)/nullif(hv.qty_basis_pcs,0)
                  -coalesce((select coalesce((select sum(c.total_cost) from erp.hpp_version_components c
                        where c.hpp_version_id=pv.id and c.source_type='POCKET_PERIOD_ALLOCATION'),0)/nullif(pv.qty_basis_pcs,0)
                      from erp.hpp_versions pv where pv.lot_id=fl.id and pv.calculated_at<statement_timestamp()
                      order by pv.calculated_at desc,pv.version_no desc limit 1),0)
          from erp.hpp_versions hv where hv.lot_id=fl.id and hv.is_current),0)::numeric dpf,fl.initial_qty_pcs::numeric qty
      from erp.fg_lots fl left join erp.qc_inspection_items qi on qi.id=fl.qc_item_id
      where fl.po_id=p_po_id and fl.lot_origin in('PRODUCTION','CONVERSION','VOIDED_PRODUCTION')
    ), grp as(
      -- The PO's cutting groups and every group of their cutting batches (a batch may hold groups of other POs; its
      -- material is pooled over all of them): pieces and the day the group was first cut.
      select g.id,g.po_id,g.cutting_batch_id batch,
        coalesce((select gt.total_pcs from erp.v_cutting_group_totals gt where gt.cutting_group_id=g.id),0)::numeric pcs,
        greatest(p_effective_date,least(v_cap,coalesce((select min(erp._cp3_business_date(mm.physical_at)) from erp.material_stock_movements mm
          where mm.source_id=g.id and mm.source_type='CUTTING_GROUP'),erp._cp3_business_date(g.cut_at)))) cd
      from erp.cutting_groups g
      where g.po_id=p_po_id or g.cutting_batch_id in(select g0.cutting_batch_id from erp.cutting_groups g0
                                                     where g0.po_id=p_po_id and g0.cutting_batch_id is not null)
    ), bt as(
      -- Each batch: pieces of its groups and the effective pieces erp.rebuild_po_hpp divides its material by.
      select gr.batch,sum(gr.pcs) spcs,
        coalesce((select vb.effective_pcs from erp.v_cutting_batch_totals vb where vb.cutting_batch_id=gr.batch),0)::numeric eff
      from grp gr where gr.batch is not null group by gr.batch
    ), mk as(
      -- When the material state was last written (a sync right after erp.rebuild_po_hpp), and tp, when the HPP posted
      -- last was rebuilt (the latest version of the PO's lots before this statement).
      select (select ms.updated_at from erp.po_hpp_gl_material_state_v1 ms where ms.po_id=p_po_id and ms.source_key='SYNC') ts,
        (select max(hv.calculated_at) from erp.hpp_versions hv join erp.fg_lots fl on fl.id=hv.lot_id
          where fl.po_id=p_po_id and hv.calculated_at<statement_timestamp()) tp
    ), fct as(
      -- Every material fact behind the PO's HPP (erp.rebuild_po_hpp): cutting issues and returns of each group (pooled per
      -- cutting batch when the group is in one; the PO-wide pool takes the PO's own groups) and non-accessory contractor
      -- issues (PO-wide over the source quantity), on the physical day erp.sync_material_cost_revaluation dates its WIP
      -- revaluation (AZ), with its value now (cur) and its value in the HPP last posted (ov): its state; else zero for a
      -- fact created after the state was written (no posted HPP has it); else, for a PO without material state
      -- (produced before AY; independent review of rev7, F1), zero for a fact created after tp and, for one created by
      -- tp, its value less the revaluations of its movement since tp (the inventory delta of a movement moves opposite
      -- to its value in the HPP); else unknown (null: the pool keeps the constant correction). anc: the revaluations of
      -- its movement after this instant are part of the change.
      select case when gr.batch is not null then 'B:'||gr.batch::text else 'G:'||gr.id::text end pool,gr.po_id=p_po_id own,
        greatest(p_effective_date,least(v_cap,erp._cp3_business_date(coalesce(rvm.pa,mm.physical_at)))) d,
        case when rvm.pa is null then -mm.qty_signed*mm.unit_cost_snapshot else 0 end cur,
        gr.id gid,ms.material_value is null and mm.system_created_at>coalesce(mk.ts,mk.tp) fresh,mm.id fid,array[mm.id] mids,
        case when ms.material_value is not null then ms.material_value
             when mk.ts is not null then case when mm.system_created_at>mk.ts then 0 end
             when mm.system_created_at>mk.tp then 0
             when mm.system_created_at<=mk.tp then -mm.qty_signed*mm.unit_cost_snapshot+coalesce((select sum(e.delta_amount)
               from erp.material_cost_revaluation_events e where e.movement_id=mm.id and e.created_at>mk.tp),0) end ov,
        case when ms.material_value is not null then ms.updated_at
             when mm.system_created_at>coalesce(mk.ts,mk.tp) then '-infinity'::timestamptz else mk.tp end anc
      from erp.material_stock_movements mm join grp gr on gr.id=mm.source_id cross join mk
      left join erp.po_hpp_gl_material_state_v1 ms on ms.po_id=p_po_id and ms.source_key='M:'||mm.id::text
      -- rev7.4: a movement reversed (erp.reverse_cutting_material_flow_before_sewing_v2) is out of the HPP (erp.rebuild_po_hpp,
      -- AY) from its reversal day on: value zero, its change dated on the reversal's physical day.
      left join lateral(select min(rv.physical_at) pa from erp.material_stock_movements rv where rv.reversal_of_id=mm.id) rvm on true
      where mm.source_type in('CUTTING_GROUP','CUTTING_GROUP_RETURN')
      union all
      select 'CONTRACTOR',false,greatest(p_effective_date,least(v_cap,erp._cp3_business_date(coalesce(cv.pa,cm.physical_at)))),
        ci.qty*ci.unit_cost_snapshot,null::uuid,false,ci.id,cv.ids,
        case when ms.material_value is not null then ms.material_value
             when mk.ts is not null then case when cv.ca>mk.ts then 0 end
             when cv.ca>mk.tp then 0
             when cv.ca<=mk.tp then ci.qty*ci.unit_cost_snapshot+coalesce((select sum(e.delta_amount)
               from erp.material_cost_revaluation_events e where e.movement_id=any(cv.ids) and e.created_at>mk.tp),0) end,
        case when ms.material_value is not null then ms.updated_at
             when cv.ca>coalesce(mk.ts,mk.tp) then '-infinity'::timestamptz else mk.tp end
      from erp.contractor_material_issue_items ci join erp.contractor_material_issues cm on cm.id=ci.issue_id
      join erp.materials mt on mt.id=ci.material_id cross join mk
      cross join lateral(select min(cm2.physical_at) pa,min(cm2.system_created_at) ca,array_agg(cm2.id) ids
        from erp.material_stock_movements cm2
        where cm2.source_type='CONTRACTOR_MATERIAL_ISSUE_ITEM' and cm2.source_id=ci.id) cv
      left join erp.po_hpp_gl_material_state_v1 ms on ms.po_id=p_po_id and ms.source_key='C:'||ci.id::text
      where cm.po_id=p_po_id and cm.status='POSTED' and mt.material_type<>'ACCESSORY'
    ), fev as(
      -- The revaluations (erp.material_cost_revaluation_events) of each fact's movement inside its change, each on the
      -- day it moved the value into WIP (AZ: the movement day of an invoice recost, today for any other recost). A
      -- correction then leaves WIP no earlier than it entered it, also for a non-invoice recost still queued when the
      -- invoice is processed (independent review of rev7, residual risk).
      select f.fid,f.pool,f.own,greatest(p_effective_date,least(v_cap,coalesce(e.effective_date,f.d))) d,-e.delta_amount dv
      from fct f cross join lateral unnest(f.mids) fm(mid)
      join erp.material_cost_revaluation_events e on e.movement_id=fm.mid and e.created_at>f.anc
      where f.ov is not null
    ), mat as(
      -- Each fact's change: its revaluations on their own days, the rest (a new fact's value, anything the revaluations
      -- do not explain) on its physical day; cur, gid and fresh only on the fact row.
      select f.pool,f.own,f.d,f.cur,f.gid,f.fresh,
        f.cur-f.ov-coalesce((select sum(v.dv) from fev v where v.fid=f.fid),0) dv
      from fct f
      union all
      select v.pool,v.own,v.d,0,null::uuid,null::boolean,v.dv from fev v
    ), matp as(
      select pool,d,cur,dv from mat union all select 'PO',d,cur,dv from mat where own
    ), pools as(
      -- Each pool: all its facts known (ok), its material correction (dvf) and its material now (mnow).
      select pool,bool_and(dv is not null) ok,coalesce(sum(dv),0) dvf,coalesce(sum(cur),0) mnow from matp group by pool
    ), lot as(
      -- The material pool of each lot as erp.rebuild_po_hpp allocates it (its cutting batch over the batch's effective
      -- pieces, else its lineage group over the group's pieces, else the PO over the PO's production pieces) and qf, the
      -- pieces behind that pool now.
      select l.*,gr.batch,
        case when gr.batch is not null then case when b.eff>0 then 'B:'||gr.batch::text else 'PO' end
             when gr.pcs>0 then 'G:'||gr.id::text else 'PO' end pool,
        case when gr.batch is not null and b.eff>0 then b.eff
             when gr.batch is null and gr.pcs>0 then gr.pcs
             else nullif((select sum(f2.initial_qty_pcs) from erp.fg_lots f2 where f2.po_id=p_po_id and f2.lot_origin='PRODUCTION'),0) end qf
      from lot0 l left join grp gr on gr.id=l.grp left join bt b on b.batch=gr.batch
    ), srcq as(
      select nullif(erp.cp6_po_source_qty_v2620c(p_po_id),0)::numeric q
    ), lotd as(
      select l.id,l.pool,l.qf,l.batch,l.src,l.cst,case when l.lot_origin='VOIDED_PRODUCTION'
          then coalesce((select avg(l2.h-l2.o) from lot0 l2 where l2.grp=l.grp and l2.lot_origin='PRODUCTION'),
                        coalesce((select p.dvf/l.qf from pools p where p.pool=l.pool and p.ok),0)
                        +coalesce((select p.dvf/(select q from srcq) from pools p where p.pool='CONTRACTOR' and p.ok),0))
          else l.h-l.o end dh
      from lot l
    ), ev as(
      select m.lot_id,greatest(p_effective_date,least(v_cap,erp._cp3_business_date(m.physical_at))) d,
        coalesce(o.movement_type,m.movement_type) k,m.qty_signed::numeric q
      from erp.fg_stock_movements m join lotd l on l.id=m.lot_id
      left join erp.fg_stock_movements o on m.movement_type='REVERSAL' and o.id=m.reversal_of_id
      where coalesce(o.movement_type,m.movement_type) in('QC_GOOD','REWORK_IN','OPENING','SALE','SALE_RETURN',
                                                         'ADJUSTMENT','BS_OUT','REBRAND_OUT','REBRAND_IN')
    ), lpp as(
      -- The pocket-fabric part of each production lot per pocket pool (erp.po_hpp_gl_pocket_by_pool_v1, the per-pool split
      -- of erp.pocket_lot_cost_v1 that erp.rebuild_po_hpp uses) now less what the last sync posted (lot state), per piece,
      -- dated as the pool's recost is (AZ rev2: not before the pool's period end while open; E when closed). Independent
      -- review of rev7.2 (1, 2): per pool and against the state, so one statement recosting several pools dates each part
      -- on its own pool's day. A lot without per-pool state: its pocket change on the caller's date (rev7.2).
      select l.id lot_id,(coalesce(x.now_amt,0)-coalesce(x.old_amt,0))/nullif(l.qty,0) dpp,
        greatest(p_effective_date,least(v_cap,coalesce((select pp.period_end from erp.pocket_periods pp where pp.id=x.pool_id),v_caller))) pd
      from lot0 l join erp.po_hpp_gl_lot_state_v1 ls on ls.lot_id=l.id and ls.pocket_by_pool is not null
      cross join lateral(select coalesce(n.pool_id,o.key::uuid) pool_id,n.amount now_amt,o.value::numeric old_amt
        from erp.po_hpp_gl_pocket_by_pool_v1(l.id) n full join jsonb_each_text(ls.pocket_by_pool) o on o.key=n.pool_id::text) x
      where l.lot_origin='PRODUCTION'
      union all
      select l.id,l.dpf,greatest(p_effective_date,least(v_cap,v_caller))
      from lot0 l left join erp.po_hpp_gl_lot_state_v1 ls on ls.lot_id=l.id
      where l.lot_origin='PRODUCTION' and ls.pocket_by_pool is null and l.dpf<>0
    ), lppa as(
      -- A voided lot takes the pocket change of the live lots of its cutting group (as its correction, lotd).
      select lot_id,dpp,pd from lpp where dpp<>0
      union all
      select v.id,sum(sp.dpp)/nullif((select count(*) from lot0 l3 where l3.grp=v.grp and l3.lot_origin='PRODUCTION'),0),sp.pd
      from lot0 v join lot0 l2 on l2.grp=v.grp and l2.lot_origin='PRODUCTION' join lpp sp on sp.lot_id=l2.id and sp.dpp<>0
      where v.lot_origin='VOIDED_PRODUCTION' group by v.id,v.grp,sp.pd
    ), dates as(
      select d from ev union select m.d from matp m join pools p on p.pool=m.pool and p.ok
      union select gr.cd from grp gr where gr.batch is not null
      union select pd from lppa
    ), daily as(
      select lot_id,d,
        sum(case when k in('QC_GOOD','REWORK_IN','OPENING') then q else 0 end) p,
        sum(case when k in('SALE','SALE_RETURN') then -q else 0 end) sd,
        sum(case when k in('ADJUSTMENT','BS_OUT','REBRAND_OUT','REBRAND_IN') then -q else 0 end) ot
      from ev group by 1,2
    ), cumq as(
      -- Pieces of each lot in FG / sold / out otherwise as of each date: running sums (independent review of rev6, M-4:
      -- no dates x movements join).
      select g.lot_id,g.d,
        sum(coalesce(dy.p,0)) over w p,sum(coalesce(dy.sd,0)) over w sd,sum(coalesce(dy.ot,0)) over w ot
      from (select l.id lot_id,dt.d from lotd l cross join dates dt) g
      left join daily dy on dy.lot_id=g.lot_id and dy.d=g.d
      window w as(partition by g.lot_id order by g.d rows unbounded preceding)
    ), pday as(
      select pool,d,sum(dv) dv from matp group by 1,2
    ), pcum as(
      -- Each pool's material correction as of each date (running sum).
      select p.pool,dt.d,sum(coalesce(pd.dv,0)) over(partition by p.pool order by dt.d rows unbounded preceding) dv
      from pools p cross join dates dt left join pday pd on pd.pool=p.pool and pd.d=dt.d where p.ok
    ), bcum as(
      -- Each batch's pieces cut by each date, scaled to its effective pieces.
      select b.batch,dt.d,
        case when b.spcs>0 then b.eff*sum(coalesce(bd.pcs,0)) over(partition by b.batch order by dt.d rows unbounded preceding)/b.spcs
             else b.eff end pcs
      from bt b cross join dates dt
      left join (select gr.batch,gr.cd,sum(gr.pcs) pcs from grp gr where gr.batch is not null group by 1,2) bd on bd.batch=b.batch and bd.cd=dt.d
    ), newg as(
      -- Groups the HPP posted last did not have (every cutting fact of the group is new).
      select m.gid from mat m where m.gid is not null group by m.gid having bool_and(m.fresh)
    ), bnew as(
      -- Effective pieces of each batch's new groups: cut by each date, and in total.
      select b.batch,dt.d,
        case when b.spcs>0 then b.eff*sum(coalesce(nd.pcs,0)) over(partition by b.batch order by dt.d rows unbounded preceding)/b.spcs else 0 end pcs,
        case when b.spcs>0 then b.eff*coalesce((select sum(g.pcs) from grp g join newg n on n.gid=g.id where g.batch=b.batch),0)/b.spcs else 0 end tot
      from bt b cross join dates dt
      left join (select gr.batch,gr.cd,sum(gr.pcs) pcs from grp gr join newg n on n.gid=gr.id where gr.batch is not null group by 1,2) nd
        on nd.batch=b.batch and nd.cd=dt.d
    ), cl as(
      -- Per-piece correction of each lot as of each date: its correction now, less the part of its pool's (and the PO's
      -- contractor) material correction whose fact is not there yet on that date. A batch divides by the (effective)
      -- pieces of the groups cut by then. A batch that got a new group since the HPP posted last also spreads its old
      -- material over the new pieces; that dilution (old material x (1/pieces by D - 1/pieces now), pieces by D counting the
      -- new groups cut by D) is dated on the new group's cut day (independent review of rev7, F4).
      select c.lot_id,c.d,c.p,c.sd,c.ot,
        l.dh+coalesce(pc.dv/nullif(case when l.pool like 'B:%' then bc.pcs else l.qf end,0),0)-coalesce(pp.dvf/l.qf,0)
          +coalesce(case when l.pool like 'B:%' and bn.tot>0
                         then (pp.mnow-pp.dvf)*(1/nullif(l.qf-bn.tot+bn.pcs,0)-1/l.qf) end,0)
          +coalesce((cc.dv-cp.dvf)/(select q from srcq),0)
          -coalesce((select sum(x.dpp) from lppa x where x.lot_id=l.id and c.d<x.pd),0) cv
      from cumq c join lotd l on l.id=c.lot_id
      left join pools pp on pp.pool=l.pool and pp.ok
      left join pcum pc on pc.pool=l.pool and pc.d=c.d
      left join bcum bc on bc.batch=l.batch and bc.d=c.d
      left join bnew bn on bn.batch=l.batch and bn.d=c.d
      left join pools cp on cp.pool='CONTRACTOR' and cp.ok
      left join pcum cc on cc.pool='CONTRACTOR' and cc.d=c.d
    ), chain as(
      -- Relabel lineage: every lot of the PO with its root lot (a lot not relabelled from a lot of this PO) and the sum of
      -- the own differences of its posted relabels (a reversed relabel adds none).
      select l.id,l.id root,0::numeric off,0 depth from lotd l where l.src is null or not exists(select 1 from lotd px where px.id=l.src)
      union all
      select l.id,c.root,c.off+case when l.cst='POSTED' then l.dh-px.dh else 0 end,c.depth+1
      from chain c join lotd l on l.src=c.id join lotd px on px.id=c.id where c.depth<100
    ), cl2 as(
      -- A relabelled lot follows its root lot (independent reviews of rev6, F6, and rev7, F3: a relabel, reversed or in a
      -- chain, moves pieces at the same correction, so nothing swings through the other account).
      select c.d,c.p,c.sd,c.ot,coalesce(cr.cv+ch.off,c.cv) cv
      from cl c left join chain ch on ch.id=c.lot_id and ch.root<>c.lot_id
      left join cl cr on cr.lot_id=ch.root and cr.d=c.d
    )
    select d,sum(cv*(p-sd-ot)) f,sum(cv*sd) c,sum(cv*ot) o from cl2 group by d order by d
  loop
    -- The change of the rounded balances since the previous date; the total is rounded once and FG takes the rest, so a
    -- pure sale day (FG -> COGS) moves no cent through WIP (independent review of rev6, m-1).
    v_f:=round(r.f+r.c+r.o,2)-round(r.c,2)-round(r.o,2);
    v_acc:=erp.po_hpp_gl_leg_add_v1(v_acc,r.d,v_f-v_sf,round(r.c,2)-v_sc,round(r.o,2)-v_so);
    v_sf:=v_f;v_sc:=round(r.c,2);v_so:=round(r.o,2);v_end:=greatest(v_end,r.d);
  end loop;
  -- The last date takes the exact remainder to the targets (rounding, or anything the balances do not explain).
  v_acc:=erp.po_hpp_gl_leg_add_v1(v_acc,v_end,v_df-v_sf,v_dc-v_sc,v_do-v_so);
  -- One event and one journal per requested date; WIP balances each date.
  for r in select key::date d,value v from jsonb_each(v_acc) order by 1 loop
    v_f:=(r.v->>'fg')::numeric;v_c:=(r.v->>'cogs')::numeric;v_o:=(r.v->>'other')::numeric;v_wip:=-(v_f+v_c+v_o);
    v_lines:='[]'::jsonb;
    if abs(v_f)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_f>0
      then jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_f,'credit',0,'po_id',p_po_id)
      else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(v_f),'po_id',p_po_id) end); end if;
    if abs(v_c)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_c>0
      then jsonb_build_object('mapping_key','COGS','debit',v_c,'credit',0,'po_id',p_po_id)
      else jsonb_build_object('mapping_key','COGS','debit',0,'credit',abs(v_c),'po_id',p_po_id) end); end if;
    -- The other bucket stays on one account, the one the AS journal would use for the PO's total other change, so each
    -- account's total equals the AS journal (independent review of rev6, M-3/F5).
    if abs(v_o)>0.005 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key',case when v_do>=0 then 'OTHER_EXPENSE' else 'OTHER_INCOME' end,
      'debit',greatest(v_o,0),'credit',greatest(-v_o,0),'po_id',p_po_id)); end if;
    if abs(v_wip)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_wip>0
      then jsonb_build_object('mapping_key','WIP','debit',v_wip,'credit',0,'po_id',p_po_id)
      else jsonb_build_object('mapping_key','WIP','debit',0,'credit',abs(v_wip),'po_id',p_po_id) end); end if;
    if jsonb_array_length(v_lines)>=2 then
      insert into erp.po_hpp_gl_events(po_id,effective_date,old_hpp_total,new_hpp_total,fg_delta,cogs_delta,other_delta)
      values(p_po_id,r.d,round(coalesce(s.hpp_total_cost,0),2),v_target_hpp,v_f,v_c,v_o)
      returning id into v_event;
      v_journal:=erp.post_journal('PO_HPP_GL_SYNC',v_event,r.d,
        'Latest corrected HPP allocation · exact minor-unit targets · dated from the goods',v_lines);
      update erp.po_hpp_gl_events set journal_entry_id=v_journal,
        effective_date=(select transaction_date from erp.journal_entries where id=v_journal) where id=v_event;
    end if;
  end loop;
  end if;
  -- The HPP this sync posted for each lot and the value of each material fact it saw: the bases of the next sync.
  insert into erp.po_hpp_gl_lot_state_v1(lot_id,po_id,hpp_per_pcs,pocket_by_pool,updated_at)
  select fl.id,p_po_id,coalesce((select max(case when coalesce(hv.qty_basis_pcs,0)>0 then hv.total_cost/hv.qty_basis_pcs else 0 end)
    from erp.hpp_versions hv where hv.lot_id=fl.id and hv.is_current),0),
    coalesce((select jsonb_object_agg(pb.pool_id::text,pb.amount) from erp.po_hpp_gl_pocket_by_pool_v1(fl.id) pb),'{}'::jsonb),
    statement_timestamp()
  from erp.fg_lots fl where fl.po_id=p_po_id and fl.lot_origin in('PRODUCTION','CONVERSION','VOIDED_PRODUCTION')
  on conflict(lot_id) do update set po_id=excluded.po_id,hpp_per_pcs=excluded.hpp_per_pcs,pocket_by_pool=excluded.pocket_by_pool,
    updated_at=excluded.updated_at;
  -- The material state is the value of each fact inside the HPP just posted, so it is written only when that HPP was
  -- rebuilt in this statement (every erp.rebuild_po_hpp caller syncs right after it; a sync without a rebuild, e.g. FG
  -- adjustment or a sale reversal, posts the HPP of the last rebuild, which the kept state still describes).
  if exists(select 1 from erp.hpp_versions hv join erp.fg_lots fl on fl.id=hv.lot_id
            where fl.po_id=p_po_id and hv.is_current and hv.calculated_at>=statement_timestamp()) then
    insert into erp.po_hpp_gl_material_state_v1(po_id,source_key,material_value,updated_at)
    select p_po_id,'M:'||mm.id::text,case when exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=mm.id) then 0
      else -mm.qty_signed*mm.unit_cost_snapshot end,statement_timestamp()
    from erp.material_stock_movements mm join erp.cutting_groups g on g.id=mm.source_id
    where mm.source_type in('CUTTING_GROUP','CUTTING_GROUP_RETURN')
      and (g.po_id=p_po_id or g.cutting_batch_id in(select g0.cutting_batch_id from erp.cutting_groups g0
                                                    where g0.po_id=p_po_id and g0.cutting_batch_id is not null))
    union all
    select p_po_id,'C:'||ci.id::text,ci.qty*ci.unit_cost_snapshot,statement_timestamp()
    from erp.contractor_material_issue_items ci join erp.contractor_material_issues cm on cm.id=ci.issue_id
    where cm.po_id=p_po_id and cm.status='POSTED'
    union all
    select p_po_id,'SYNC',0,statement_timestamp()
    on conflict(po_id,source_key) do update set material_value=excluded.material_value,updated_at=excluded.updated_at;
  end if;

  insert into erp.po_hpp_gl_state(po_id,base_output_qty,hpp_total_cost,fg_value,cogs_value,other_out_value,updated_at)
  values(p_po_id,v_target_qty,v_target_hpp,v_target_fg,v_target_cogs,v_target_other,statement_timestamp())
  on conflict(po_id) do update set base_output_qty=excluded.base_output_qty,
    hpp_total_cost=excluded.hpp_total_cost,fg_value=excluded.fg_value,
    cogs_value=excluded.cogs_value,other_out_value=excluded.other_out_value,updated_at=statement_timestamp();
end
$function$;
insert into erp.schema_migrations(version,description) values('v2.6.20ay','T1_FAMILY development install of AY (PO HPP corrections dated from the goods); not a release package');
commit;
